7	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
8	import { paymentMetadataHandler } from './paymentMetadata';
9	import { sendMagicLinkEmail } from './marketingCloud';
10	import type { SsrReq, SsrRes } from './types';
11	
12	const PAYMENTS_URL = 'https://payments.example.demandware.net/metadata';
13	
14	/** Duration of the deliberate synchronous block used to occupy the event loop. */
15	const BLOCK_MS = 200;
16	/** Allowance for timer resolution when asserting on wall-clock durations. */
17	const TIMER_TOLERANCE_MS = 5;
18	/** Upper bound on how long to wait for Node to report an unhandled rejection. */
19	const REJECTION_SETTLE_TIMEOUT_MS = 1_000;
20	
21	type MockRes = SsrRes & { statusCode?: number; body?: unknown };
22	
23	function createMockRes(): MockRes {
24	  // Built incrementally: every member of SsrRes is assigned immediately below,
25	  // so the object is complete before it is returned.
26	  const res = {} as MockRes;
27	  res.status = vi.fn().mockImplementation((code: number) => {
28	    res.statusCode = code;
29	    return res;
30	  });
31	  res.json = vi.fn().mockImplementation((data: unknown) => {
32	    res.body = data;
33	    return res;
34	  });
35	  res.send = vi.fn().mockImplementation((data: unknown) => {
36	    res.body = data;
37	    return res;
38	  });
39	  res.setHeader = vi.fn().mockReturnValue(res);
40	  res.set = vi.fn().mockReturnValue(res);
41	  return res;
42	}
