55	/**
56	 * As-is baseline evidence for SFCC-681 (TSD-SFCC-681, "MRT Application Topology").
57	 *
58	 * These exercise the real SSR handler functions rather than stand-ins, so the TSD's
59	 * Problem Statement and Options Analysis rest on reproducible evidence rather than
60	 * assertion.
61	 *
62	 * They document CURRENT behaviour. The first two are expected to change once the
63	 * safeguards in the TSD's §5 are implemented, and should then be updated to assert
64	 * the fixed behaviour rather than deleted. The third documents a permanent property
65	 * of any single-process model and is expected to keep passing unchanged.
66	 *
67	 * Every fetch is mocked; nothing here contacts a real network endpoint.
68	 */
69	describe('SSR shared-process blast radius (SFCC-681 as-is baseline)', () => {
70	  beforeEach(() => {
71	    vi.stubEnv('MARKETING_CLOUD_CLIENT_ID', 'test-client-id');
72	    vi.stubEnv('MARKETING_CLOUD_CLIENT_SECRET', 'test-client-secret');
73	    vi.stubEnv('MARKETING_CLOUD_SUBDOMAIN', 'test-subdomain');
74	
75	    // getConfig returns the full PWA Kit runtime config; only the fields these two
76	    // handlers actually read are stubbed here.
77	    vi.mocked(getConfig).mockReturnValue({
78	      app: {
79	        sfPayments: { metadataUrl: PAYMENTS_URL },
80	        login: { resetPassword: { landingPath: '/reset-password' }, passwordless: {} },
81	      },
82	    } as ReturnType<typeof getConfig>);
83	
84	    vi.stubGlobal(
85	      'fetch',
86	      vi.fn((input: string | URL) => {
87	        const href = String(input);
88	        // Each branch stubs only the Response members the handlers touch: ok, status, json.
89	        if (href.includes('payments.example.demandware.net')) {
90	          return Promise.resolve({ ok: true, json: () => Promise.resolve({ paymentMethodTypes: {} }) } as Response);
91	        }
92	        if (href.includes('auth.marketingcloudapis.com')) {
93	          return Promise.resolve({ ok: true, json: () => Promise.resolve({ access_token: 'fake-token' }) } as Response);
94	        }
95	        if (href.includes('rest.marketingcloudapis.com')) {
96	          // Marketing Cloud's send-email endpoint is down. The token exchange above
97	          // still succeeds, so only the send call fails.
98	          return Promise.resolve({ ok: false, status: 503 } as Response);
99	        }
100	        return Promise.reject(new Error(`Unexpected fetch in test: ${href}`));
101	      }),
102	    );
103	  });
104	
105	  afterEach(() => {
106	    vi.unstubAllGlobals();
107	    vi.unstubAllEnvs();
108	    vi.clearAllMocks();
109	  });
110	
111	  test('an aggregating caller loses a successful result when a sibling integration rejects', async () => {
112	    const paymentsRes = createMockRes();
113	    const magicLinkRes = createMockRes();
114	
115	    const paymentsCall = paymentMetadataHandler({}, paymentsRes);
116	    const magicLinkCall = sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');
117	
118	    // Ground truth, established independently of one another: payment metadata
119	    // genuinely succeeds, and the magic-link send genuinely rejects uncaught.
120	    // sendMagicLinkEmail has no try/catch around its Marketing Cloud call, unlike
121	    // paymentMetadataHandler and jwksCaching, which both catch their own fetch
122	    // failures and convert them into HTTP error responses.
123	    const [paymentsOutcome, magicLinkOutcome] = await Promise.allSettled([paymentsCall, magicLinkCall]);
124	    expect(paymentsOutcome.status).toBe('fulfilled');
125	    expect(magicLinkOutcome.status).toBe('rejected');
126	    expect(paymentsRes.body).toEqual(expect.objectContaining({ paymentMethodTypes: {} }));
127	
128	    // What a caller aggregating "I need both of these" experiences today. The
129	    // payment data was computed successfully, as proven above, but Promise.all
130	    // discards it the moment its sibling rejects, leaving the caller no way to
131	    // recover it.
132	    const paymentsRes2 = createMockRes();
133	    const magicLinkRes2 = createMockRes();
134	    await expect(
135	      Promise.all([
136	        paymentMetadataHandler({}, paymentsRes2),
137	        sendMagicLinkEmail(createMockReq(), magicLinkRes2, '/reset-password', 'reset-template'),
138	      ]),
139	    ).rejects.toThrow(/Marketing Cloud/i);
140	  });
141	
142	  test('the shipped route shape leaves the request unanswered when its integration fails', async () => {
143	    const magicLinkRes = createMockRes();
144	
145	    // The real ssr.js route handlers never await or catch this call, so the only
146	    // thing between the rejection and an undetected failure is pwa-kit-runtime's
147	    // own global handler (build-remote-server.js registers process.on(
148	    // 'unhandledRejection', catchAndLog), which logs and nothing more).
149	    // Registering an equivalent listener here reproduces that real safety net,
150	    // lets the test assert the rejection genuinely goes unhandled by application
151	    // code, and stops Vitest reporting it as a stray run-failing error.
152	    let capturedRejection: unknown;
153	    const onUnhandledRejection = (reason: unknown) => {
154	      capturedRejection = reason;
155	    };
156	    process.once('unhandledRejection', onUnhandledRejection);
157	
158	    try {
159	      // Reproduces the exact shape of the shipped call sites in ssr.js: the
160	      // passwordless-login and reset-password routes both invoke
161	      // sendMagicLinkEmail inside a .then() callback without returning, awaiting
162	      // or chaining it. `void` marks the promises as deliberately unobserved for
163	      // the linter only; it attaches no handler and leaves the orphaned-promise
164	      // behaviour under test unchanged.
165	      void Promise.resolve().then(() => {
166	        void sendMagicLinkEmail(createMockReq(), magicLinkRes, '/reset-password', 'reset-template');
167	      });
168	
169	      // Node reports unhandled rejections on a macrotask boundary, so poll rather
170	      // than sleeping for a fixed duration.
171	      await vi.waitFor(
172	        () => {
173	          expect(capturedRejection).toBeInstanceOf(Error);
174	        },
175	        { timeout: REJECTION_SETTLE_TIMEOUT_MS, interval: 10 },
176	      );
177	      expect((capturedRejection as Error).message).toMatch(/Marketing Cloud/i);
178	
179	      // The other half of the finding: the shopper is told nothing at all. The
180	      // framework's handler only logs, and nothing in that path touches this
181	      // response. The request is left to run out MRT's execution ceiling and
182	      // return a generic 502.
183	      // eslint-disable-next-line @typescript-eslint/unbound-method -- plain vi.fn() mocks with no `this` dependency; standard Vitest call-count assertion.
184	      expect(magicLinkRes.send).not.toHaveBeenCalled();
185	      // eslint-disable-next-line @typescript-eslint/unbound-method -- see above
186	      expect(magicLinkRes.json).not.toHaveBeenCalled();
187	      // eslint-disable-next-line @typescript-eslint/unbound-method -- see above
188	      expect(magicLinkRes.status).not.toHaveBeenCalled();
189	    } finally {
190	      process.removeListener('unhandledRejection', onUnhandledRejection);
191	    }
192	  });
193	
194	  test('a synchronous CPU-bound operation blocks unrelated concurrent work', async () => {
195	    // Nothing is mocked here. This is a property of Node's single-threaded event
196	    // loop rather than of any integration's code, and it is not addressable by
197	    // connection pools, which govern sockets rather than who holds the JS thread.
198	    // It therefore documents a permanent trade-off of the single-application
199	    // model rather than a defect to be fixed.
200	    let fastResolvedAt = 0;
201	    const start = Date.now();
202	
203	    const fastRequest = Promise.resolve().then(() => {
204	      fastResolvedAt = Date.now();
205	    });
206	
207	    const blockUntil = Date.now() + BLOCK_MS;
208	    while (Date.now() < blockUntil) {
209	      // Busy-wait, standing in for a heavy synchronous operation such as a large
210	      // JSON.parse or an expensive regex inside an integration handler.
211	    }
212	
213	    await fastRequest;
214	    const fastRequestDelay = fastResolvedAt - start;
215	
216	    // The fast work should resolve almost immediately. Instead it waits out the
217	    // entire blocking operation, because both share one event loop.
218	    expect(fastRequestDelay).toBeGreaterThanOrEqual(BLOCK_MS - TIMER_TOLERANCE_MS);
219	  });
220	});
